FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR

VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR

VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR

VAR
    head          : DINT := 1;
    tail          : DINT := 1;
    prev_enqueue  : BOOL := FALSE;
    prev_dequeue  : BOOL := FALSE;
    internalCount : DINT := 0;
END_VAR

IF reset THEN
    head := 1;
    tail := 1;
    internalCount := 0;
    elementCount := 0;
    status := 16#0000;

ELSIF enqueue AND NOT prev_enqueue THEN
    IF internalCount < capacity THEN
        buffer[DINT_TO_INT(tail)] := item;
        tail := (tail MOD capacity) + 1;
        internalCount := internalCount + 1;
        elementCount := internalCount;
        status := 16#0000;
    ELSE
        status := 16#8002;
    END_IF;

ELSIF dequeue AND NOT prev_dequeue THEN
    IF internalCount > 0 THEN
        item := buffer[DINT_TO_INT(head)];
        head := (head MOD capacity) + 1;
        internalCount := internalCount - 1;
        elementCount := internalCount;
        status := 16#0000;
    ELSE
        status := 16#8001;
    END_IF;

ELSE
    status := 16#0000;
END_IF;

prev_enqueue := enqueue;
prev_dequeue := dequeue;

END_FUNCTION_BLOCK
